CREATE COLUMN TABLE "TEST_AP"."ATC1" ("AbsEntry" INTEGER CS_INT NOT NULL , "Line" INTEGER CS_INT NOT NULL , "srcPath" NCLOB MEMORY THRESHOLD 1000, "trgtPath" NCLOB MEMORY THRESHOLD 1000, "FileName" NVARCHAR(254), "FileExt" NVARCHAR(8), "Date" LONGDATE CS_LONGDATE, "UsrID" INTEGER CS_INT, "Copied" NVARCHAR(1) DEFAULT 'N', "Override" NVARCHAR(1) DEFAULT 'N', "subPath" NVARCHAR(254), "FreeText" NVARCHAR(100), PRIMARY KEY ("AbsEntry", "Line")) UNLOAD PRIORITY 5  AUTO MERGE 